def ev_status(start,end,today):
    import datetime as dt
    def p(x):
        try: return dt.date.fromisoformat(str(x)[:10])
        except: return None
    t=dt.date.fromisoformat(today); s=p(start); e=p(end)
    if s is None: return None
    if e is None: e=s
    if e<t: return "終了"
    if s<=t<=e: return "開催中"
    return "開催予定"
